import { deflateRawSync } from 'node:zlib';

/**
 * Builds real ZIP archives for tests.
 *
 * A hand-rolled archive is deliberate: the point of `zip-ingest.ts` is to
 * survive hostile input, and a fixture generated by a library would only prove
 * that library round-trips. Here every byte of the local header, the central
 * directory and the end-of-central-directory record is under test control, so
 * a test can set an absurd `uncompressedSize`, an encrypted flag, or a
 * `../../` name that no sane zip writer would ever emit.
 *
 * Method 0 is stored (bytes verbatim), method 8 is raw deflate, which is what
 * a real `zip -r` uses and what a zip bomb relies on.
 */

export type ZipEntrySpec = {
	name: string;
	data: Buffer;
	/** Default: stored for small payloads, deflate for anything large. */
	deflate?: boolean;
	/** Sets bit 0 of the general purpose flag, i.e. "encrypted". */
	encrypted?: boolean;
	/** Override the size written in the headers without changing the payload. */
	declaredUncompressedSize?: number;
	declaredCompressedSize?: number;
};

const CRC_TABLE = (() => {
	const table = new Int32Array(256);
	for (let i = 0; i < 256; i += 1) {
		let value = i;
		for (let bit = 0; bit < 8; bit += 1) {
			value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
		}
		table[i] = value;
	}
	return table;
})();

function crc32(buffer: Buffer): number {
	let value = 0xffffffff;
	for (let i = 0; i < buffer.length; i += 1) {
		value = CRC_TABLE[(value ^ buffer[i]) & 0xff] ^ (value >>> 8);
	}
	return (value ^ 0xffffffff) >>> 0;
}

export function makeZip(entries: ZipEntrySpec[]): Buffer {
	const localParts: Buffer[] = [];
	const centralParts: Buffer[] = [];
	let offset = 0;

	for (const entry of entries) {
		const useDeflate = entry.deflate ?? entry.data.length > 4096;
		const compressed = useDeflate ? deflateRawSync(entry.data) : entry.data;
		const nameBytes = Buffer.from(entry.name, 'utf8');
		const crc = crc32(entry.data);
		const compressedSize = entry.declaredCompressedSize ?? compressed.length;
		const uncompressedSize = entry.declaredUncompressedSize ?? entry.data.length;
		const flags = entry.encrypted ? 0x0001 : 0x0000;
		const method = useDeflate ? 8 : 0;

		const local = Buffer.alloc(30);
		local.writeUInt32LE(0x04034b50, 0);
		local.writeUInt16LE(20, 4);
		local.writeUInt16LE(flags, 6);
		local.writeUInt16LE(method, 8);
		local.writeUInt16LE(0, 10);
		local.writeUInt16LE(0x21, 12);
		local.writeUInt32LE(crc, 14);
		local.writeUInt32LE(compressedSize, 18);
		local.writeUInt32LE(uncompressedSize, 22);
		local.writeUInt16LE(nameBytes.length, 26);
		local.writeUInt16LE(0, 28);

		localParts.push(local, nameBytes, compressed);

		const central = Buffer.alloc(46);
		central.writeUInt32LE(0x02014b50, 0);
		central.writeUInt16LE(20, 4);
		central.writeUInt16LE(20, 6);
		central.writeUInt16LE(flags, 8);
		central.writeUInt16LE(method, 10);
		central.writeUInt16LE(0, 12);
		central.writeUInt16LE(0x21, 14);
		central.writeUInt32LE(crc, 16);
		central.writeUInt32LE(compressedSize, 20);
		central.writeUInt32LE(uncompressedSize, 24);
		central.writeUInt16LE(nameBytes.length, 28);
		central.writeUInt16LE(0, 30);
		central.writeUInt16LE(0, 32);
		central.writeUInt16LE(0, 34);
		central.writeUInt16LE(0, 36);
		central.writeUInt32LE(0, 38);
		central.writeUInt32LE(offset, 42);

		centralParts.push(central, nameBytes);
		offset += local.length + nameBytes.length + compressed.length;
	}

	const centralDirectory = Buffer.concat(centralParts);
	const localSection = Buffer.concat(localParts);

	const end = Buffer.alloc(22);
	end.writeUInt32LE(0x06054b50, 0);
	end.writeUInt16LE(0, 4);
	end.writeUInt16LE(0, 6);
	end.writeUInt16LE(entries.length, 8);
	end.writeUInt16LE(entries.length, 10);
	end.writeUInt32LE(centralDirectory.length, 12);
	end.writeUInt32LE(localSection.length, 16);
	end.writeUInt16LE(0, 20);

	return Buffer.concat([localSection, centralDirectory, end]);
}

export const PDF_BYTES = Buffer.from('%PDF-1.7\n1 0 obj\n<<>>\nendobj\n', 'latin1');
export const DOCX_BYTES = Buffer.concat([
	Buffer.from([0x50, 0x4b, 0x03, 0x04]),
	Buffer.from('word/document.xml-bytes')
]);
export const HTML_BYTES = Buffer.from('<html><body>no soy un pdf</body></html>');
